<script>
(() => { const list=document.getElementById('questions'); if(!list||list.dataset.ready)return; list.dataset.ready='1'; let questions=window.questionnaireInitialQuestions||[]; const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;'); const render=()=>{list.innerHTML=questions.map((q,i)=>`<section class="border rounded p-3 mb-3"><div class="d-flex justify-content-between gap-3"><h3 class="h6">Pertanyaan ${i+1}</h3><button class="btn btn-sm btn-outline-danger" data-remove="${i}" type="button">Hapus</button></div><div class="row g-3"><div class="col-md-4"><label class="form-label">Tipe</label><select class="form-select" data-type="${i}" name="questions[${i}][type]"><option value="multiple_choice" ${q.type==='multiple_choice'?'selected':''}>Pilihan ganda</option><option value="likert" ${q.type==='likert'?'selected':''}>Skala Likert 5 poin</option><option value="short_text" ${q.type==='short_text'?'selected':''}>Isian singkat</option></select></div><div class="col-md-8"><label class="form-label">Pertanyaan</label><input class="form-control" name="questions[${i}][text]" value="${esc(q.text)}" required></div><div class="col-12"><label class="form-label">Petunjuk (opsional)</label><input class="form-control" name="questions[${i}][help_text]" value="${esc(q.help_text)}"></div><div class="col-12"><input type="hidden" name="questions[${i}][is_required]" value="0"><div class="form-check"><input class="form-check-input" type="checkbox" name="questions[${i}][is_required]" value="1" ${q.is_required?'checked':''}><label class="form-check-label">Wajib diisi</label></div></div><div class="col-12" data-options="${i}"></div></div></section>`).join(''); list.querySelectorAll('[data-options]').forEach(el=>{const i=el.dataset.options,q=questions[i]; if(q.type==='likert')el.innerHTML='<div class="alert alert-light mb-0">Skala 1 hingga 5 akan dibuat otomatis.</div>'; if(q.type==='short_text')el.innerHTML='<div class="alert alert-light mb-0">Responden mengisi jawaban singkat.</div>'; if(q.type==='multiple_choice')el.innerHTML=`<label class="form-label">Opsi jawaban</label>${(q.options||[]).map((o,j)=>`<div class="input-group mb-2"><input class="form-control" name="questions[${i}][options][${j}][label]" value="${esc(o.label)}" required><button class="btn btn-outline-danger" data-option-remove="${i}:${j}" type="button">Hapus</button></div>`).join('')}<button class="btn btn-sm btn-outline-secondary" data-option-add="${i}" type="button">Tambah opsi</button>`});}; list.addEventListener('click',e=>{let i=e.target.dataset.remove;if(i!==undefined){questions.splice(i,1);render()}let a=e.target.dataset.optionAdd;if(a!==undefined){questions[a].options.push({label:''});render()}let r=e.target.dataset.optionRemove;if(r){let [qi,oi]=r.split(':');questions[qi].options.splice(oi,1);render()}}); list.addEventListener('change',e=>{let i=e.target.dataset.type;if(i!==undefined){questions[i].type=e.target.value;if(e.target.value==='multiple_choice'&&(!questions[i].options||questions[i].options.length<2))questions[i].options=[{label:''},{label:''}];render()}});document.getElementById('add-question')?.addEventListener('click',()=>{questions.push({type:'multiple_choice',text:'',help_text:'',is_required:true,options:[{label:''},{label:''}]});render()});render();})();
</script>
